import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { hundredths } from './rates';
import { Session } from './session';

/** A member of a pool with its share percent: a person (personId), or another pool (poolId). A retired
 *  person counts 0.00 toward the pool's total. */
export interface PoolMemberView {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  /** Their cut of the pool's pot, two decimals (0.00 when retired or on hold on the sheet's today, their
   *  share spread over the others with a cut); null when the pool is unbalanced or
   *  has no pot. A pool in another has its cut there as its pot; one in none has the sheet's pot. */
  cut: string | null;
}

/** A pool: its members, their total share, and whether that is exactly 100.00. */
/** A member to add: a person or another pool, by id. */
export type PoolMemberChoice = { personId: number } | { poolId: number };

export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

// The active sheet's pools, re-read from the server each time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** In the order they were added. */
  readonly pools = signal<PoolView[]>([]);
  private loads = 0;

  /** Each person's cuts across every pool they are a member of, added up, in hundredths, by person id; a pool
   *  that shows no cuts adds nothing. */
  readonly cutCents = computed(() => {
    const out = new Map<number, bigint>();
    for (const pool of this.pools()) {
      for (const m of pool.members) {
        if (m.personId !== null && m.cut !== null) {
          out.set(m.personId, (out.get(m.personId) ?? 0n) + hundredths(m.cut));
        }
      }
    }
    return out;
  });

  /** Re-read the active sheet's pools from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.pools.set([]);
    if (!user || !sid) return null;
    try {
      const pools = await firstValueFrom(this.http.get<PoolView[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.pools.set(pools);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load pools (${e.status}).` : 'Could not load pools.';
    }
  }

  /** Add a pool; an error message when refused (blank, or the name already taken). */
  async add(name: string): Promise<string | null> {
    const n = name.trim();
    if (!n) return 'Enter a pool name.';
    return this.post('', { name: n }, 'add pool');
  }

  /** Add a person or another pool to a pool with a share; an error message when refused (already in it, a
   *  bad share, or a pool that would contain itself, is already in one, or would make a chain too deep). The
   *  pools are re-read after: a pool in another takes its pot from its cut there. */
  async addMember(poolId: number, member: PoolMemberChoice | null, share: string): Promise<string | null> {
    const s = share.trim();
    if (member === null) return 'Choose a person or a pool.';
    if (!SHARE.test(s) || Number(s) <= 0 || Number(s) > 100) {
      return 'Enter a share more than 0.00 and at most 100.00, in two decimals.';
    }
    const err = await this.post(`/${poolId}/members`, { ...member, share: s }, 'add pool member');
    if (!err) await this.reread();
    return err;
  }

  /** Re-read the active sheet's pools without clearing the ones shown meanwhile. */
  private async reread(): Promise<void> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return;
    const load = ++this.loads;
    try {
      const pools = await firstValueFrom(this.http.get<PoolView[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads && this.session.sheetId() === sid) this.pools.set(pools);
    } catch {
      // the pool just saved is shown already; the rest are re-read on the next load
    }
  }

  private async post(path: string, body: object, what: string): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const saved = await firstValueFrom(
        this.http.post<PoolView>(this.url(sid) + path, body, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.pools.update((ps) =>
          ps.some((p) => p.id === saved.id) ? ps.map((p) => (p.id === saved.id ? saved : p)) : [...ps, saved],
        );
      }
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string') return e.error.message;
      return e instanceof HttpErrorResponse ? `Could not ${what} (${e.status}).` : `Could not ${what}.`;
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/pools`;
  }
}
import { Component, inject, input, signal } from '@angular/core';
import { People } from '../../core/people';
import { PoolMemberChoice, PoolView, Pools } from '../../core/pools';

// One pool's row: its members with their shares, its total share and whether it is balanced (exactly
// 100.00; a retired member counts 0.00), each member's cut of the pool's pot while balanced (the sheet's pot, or
// its cut in the pool it is a member of), and a form adding a person or another pool (pool:<name>) with a share.
@Component({
  selector: 'app-pool-row',
  template: `
    @let p = pool();
    <h3 data-testid="pool-name">{{ p.name }}</h3>
    <p>
      Total share: <strong data-testid="pool-total-share">{{ p.totalShare }}</strong>
      Balanced: <strong data-testid="pool-balanced">{{ p.balanced ? 'yes' : 'no' }}</strong>
    </p>
    <ul [attr.aria-label]="'Members of ' + p.name">
      @for (m of p.members; track memberKey(m)) {
        <li [attr.data-testid]="'pool-member-' + p.name + '-' + memberKey(m)">
          <span data-testid="pool-member-name">{{ m.name }}</span>
          <span data-testid="pool-share">{{ m.share }}</span>
          <span data-testid="pool-cut">{{ m.cut ?? '' }}</span>
          @if (m.retired) {
            <span data-testid="pool-member-retired">retired</span>
          }
        </li>
      }
    </ul>
    <form (submit)="add($event)">
      <label [for]="'pool-member-select-' + p.id">Member</label>
      <select
        [id]="'pool-member-select-' + p.id"
        data-testid="pool-member-select"
        (change)="member.set(selected($event)); error.set(null)"
      >
        <option value="" [selected]="member() === ''">Choose a person or a pool</option>
        @for (person of people.people(); track person.id) {
          <option [value]="'person:' + person.id" [selected]="member() === 'person:' + person.id">{{ person.name }}</option>
        }
        @for (other of pools.pools(); track other.id) {
          <option [value]="'pool:' + other.id" [selected]="member() === 'pool:' + other.id">pool:{{ other.name }}</option>
        }
      </select>
      <label [for]="'pool-member-share-' + p.id">Share %</label>
      <input
        [id]="'pool-member-share-' + p.id"
        data-testid="pool-member-share"
        inputmode="decimal"
        [value]="share()"
        (input)="share.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="pool-member-add" [disabled]="saving()">Add member</button>
      @if (error(); as err) {
        <p role="alert" data-testid="pool-error">{{ err }}</p>
      }
    </form>
  `,
})
export class PoolRow {
  readonly pool = input.required<PoolView>();
  protected readonly people = inject(People);
  protected readonly pools = inject(Pools);
  /** The chosen member: person:<id>, pool:<id>, or blank for none. */
  protected readonly member = signal('');
  protected readonly share = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected selected(e: Event): string {
    return (e.target as HTMLSelectElement).value;
  }

  /** A person member by their id; a pool member as pool-<name>. */
  protected memberKey(m: PoolView['members'][number]): string {
    return m.poolId !== null ? 'pool-' + m.name : String(m.personId);
  }

  private choice(): PoolMemberChoice | null {
    const [kind, id] = this.member().split(':');
    if (!id) return null;
    return kind === 'pool' ? { poolId: Number(id) } : { personId: Number(id) };
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.pools.addMember(this.pool().id, this.choice(), this.share());
      if (err) this.error.set(err);
      else {
        this.member.set('');
        this.share.set('');
      }
    } finally {
      this.saving.set(false);
    }
  }
}

// The sheet's pools: a form adds one (a blank name, or one already taken, is refused), and each pool's row
// shows its members and adds more.
@Component({
  selector: 'app-pools',
  imports: [PoolRow],
  template: `
    <section aria-label="Pools" data-testid="pools">
      <h2>Pools</h2>
      <form (submit)="add($event)" data-testid="pool-form">
        <label for="pool-form-name">Name</label>
        <input
          id="pool-form-name"
          data-testid="pool-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="pool-form-submit" [disabled]="saving()">Add pool</button>
        @if (error(); as err) {
          <p role="alert" data-testid="pool-form-error">{{ err }}</p>
        }
      </form>
      @for (p of pools.pools(); track p.id) {
        <app-pool-row [pool]="p" [attr.data-testid]="'pool-row-' + p.name" />
      }
    </section>
  `,
})
export class PoolsPanel {
  protected readonly pools = inject(Pools);
  protected readonly name = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.pools.add(this.name());
      if (err) this.error.set(err);
      else this.name.set('');
    } finally {
      this.saving.set(false);
    }
  }
}
